<script setup lang="ts">
import {ref,computed} from 'vue';import {IconPencil,IconCube,IconStar,IconSend,IconFileExport,IconClock,IconShoppingBag,IconCrown,IconChevronRight,IconLayoutGrid,IconList,IconDots,IconDownload,IconHeartFilled,IconMessage,IconSearch} from '@tabler/icons-vue';import Rect from './Rect.vue';import Art from './Art.vue';import {studio,referenceMode,show,saveParameters} from './state';import {seals,select} from '../store'
const tab=ref('我的印章'),filter=ref('全部印章'),style=ref('全部风格'),query=ref(''),list=ref(false),sort=ref('创建时间')
const names=['山河未阑','云水长生','观止','万象更新','清风明月','不负山河','知行合一','一蓑烟雨']
const tabs=['我的印章','作品集','收藏夹','发布展示','导出文件','创作记录','订单管理','会员权益']
const referenceItems=computed(()=>{const items=names.map((name,i)=>({name,i})).filter(r=>filter.value!=='原创'||r.i===0);return sort.value==='名称'?items.sort((a,b)=>a.name.localeCompare(b.name)):items})
const actual=computed(()=>{let r=seals.value.filter(s=>s.title.includes(query.value)&&(filter.value==='全部印章'||filter.value==='原创'&&s.source_kind==='native_typeset'||filter.value==='图示'&&s.source_kind==='reference'));return sort.value==='名称'?r.sort((a,b)=>a.title.localeCompare(b.title)):r})
function download(i:number){if(referenceMode.value)show('download','参考作品导出',{image:'/assets/museum/account-'+i+'.png'});else{const s=actual.value[i];if(s){select(s.id);show('export','导出实际作品',{seal:s})}}}
function chooseTab(t:string){tab.value=t;if(t!=='我的印章'){referenceMode.value=false;localStorage.setItem('yinmai-reference-mode','false')};if(['发布展示','订单管理','会员权益'].includes(t))show('account-feature',t);else if(t==='创作记录')show('history','实际创作记录');else if(t==='导出文件')show('exports','导出文件',{seals:seals.value})}
</script>
<template>
<Rect :x="170" :y="0" :w="1502" :h="247" plain><Art name="account-hero" alt="山河未阑，印章与山水背景"/></Rect>
<Rect :x="220" :y="80" :w="143" :h="143" plain><button class="im-profile-avatar" @click="show('profile','编辑个人资料')"><Art name="account-avatar" alt="个人头像参考"/><IconPencil :size="19"/></button></Rect>
<Rect :x="394" :y="104" :w="466" :h="117" plain><div class="im-profile"><h1>{{studio.profile.name}} <button class="im-vip" @click="show('account-feature','会员权益')"><IconCrown :size="13"/> VIP</button></h1><p>{{studio.profile.bio}}</p><div><button @click="show('profile','编辑个人资料')">传统文化爱好者</button><RouterLink to="/workspace">AI创作探索者</RouterLink><RouterLink to="/customize">印章设计师</RouterLink></div></div></Rect>
<Rect :x="190" :y="246" :w="1463" :h="118" title="个人资产"><div class="im-account-stats"><button v-for="(s,i) in tabs" @click="chooseTab(s)"><component :is="[IconCube,IconCube,IconStar,IconSend,IconFileExport,IconClock,IconShoppingBag,IconCrown][i]" :size="36"/><div><b>{{referenceMode?['128','36','68','12','245','320','18','VIP'][i]:[studio.counts.seals,studio.counts.designs,studio.counts.favorites,0,seals.reduce((n,s)=>n+s.artifacts.length,0),studio.counts.designs,0,'本机'][i]}}</b><span>{{s}}</span><small>{{['累计生成作品','创建的项目','收藏的印章','已公开作品','图片 / 矢量 / 模型','生成历史','已完成订单',referenceMode?'2025.12.31 到期':'无付费服务'][i]}}</small></div></button></div></Rect>
<Rect :x="190" :y="378" :w="1031" :h="562" title="我的作品"><div class="im-account-main"><div class="im-account-tabs"><button v-for="t in tabs" :class="{active:tab===t}" @click="chooseTab(t)">{{t}}</button></div><div class="im-account-toolbar"><select v-model="filter" aria-label="作品类型"><option>全部印章</option><option>原创</option><option>图示</option></select><select v-model="style" aria-label="作品风格"><option>全部风格</option><option>汉印</option><option>明清</option><option>秦篆</option></select><select v-model="sort" aria-label="作品排序"><option>创建时间</option><option>名称</option></select><label><IconSearch :size="17"/><input v-model="query" aria-label="搜索我的印章" placeholder="搜索我的印章…"></label><button :class="{active:!list}" aria-label="网格视图" @click="list=false"><IconLayoutGrid :size="20"/></button><button :class="{active:list}" aria-label="列表视图" @click="list=true"><IconList :size="20"/></button></div>
<div v-if="tab==='作品集'&&!referenceMode" class="im-real-designs"><article v-for="d in studio.designs"><h3>{{d.title}}</h3><p>{{d.created_at}}</p><button @click="show('design',d.title,{design:d})">查看保存参数</button></article><p v-if="!studio.designs.length">还没有保存方案。<RouterLink to="/customize">开始定制</RouterLink></p></div>
<div v-else-if="tab==='收藏夹'&&!referenceMode" class="im-real-designs"><RouterLink v-for="id in studio.favorites" :to="'/catalog/'+id">{{id}}　查看收藏</RouterLink><p v-if="!studio.favorites.length">收藏夹为空。</p></div>
<div v-else-if="referenceMode" class="im-account-grid" :class="{list}"><article v-for="{name,i} in referenceItems" v-show="name.includes(query)&&(style==='全部风格'||['汉印','宋式','秦篆','明清'][i%4]===style)" :class="{selected:i===0}"><button class="im-account-art" @click="show('image',name+' · 视觉示例',{image:'/assets/museum/account-'+i+'.png'})"><Art :name="'account-'+i" :alt="name+'作品概念参考'"/></button><button class="im-account-more" :aria-label="name+'更多操作'" @click="show('download',name+' · 视觉示例',{image:'/assets/museum/account-'+i+'.png'})"><IconDots :size="20"/></button><h3>{{name}}</h3><p>{{['汉印 · 阳刻','宋式 · 阴刻','秦篆 · 朱文','明清 · 混合'][i%4]}}</p><time>2024.{{i<2?'12':'11'}}.{{['05','03','28','25','20','15','10','08'][i]}}</time><footer><span><IconHeartFilled :size="16"/> {{[128,86,105,92,76,134,68,91][i]}}</span><span><IconMessage :size="14"/> {{[12,8,6,11,4,17,5,9][i]}}</span><button :aria-label="'导出'+name" @click="download(i)"><IconDownload :size="17"/></button><button :aria-label="name+'操作'" @click="show('download',name,{image:'/assets/museum/account-'+i+'.png'})"><IconDots :size="17"/></button></footer></article></div>
<div v-else class="im-account-grid" :class="{list}"><article v-for="(s,i) in actual" :key="s.id"><button class="im-account-art" @click="select(s.id);$router.push('/reconstruction')"><img :src="s.original_url" :alt="s.title"></button><h3>{{s.title}}</h3><p>{{s.source_kind}}</p><time>{{s.created_at?.slice(0,10)}}</time><footer><button @click="download(i)"><IconDownload :size="17"/> 导出</button></footer></article><p v-if="!actual.length" class="im-empty">暂无实际作品。<RouterLink to="/upload">上传印谱</RouterLink></p></div></div></Rect>
<Rect :x="1238" :y="378" :w="416" :h="236" title="最近创作"><header class="im-section-heading"><h2>最近创作</h2><button class="im-subtle" @click="show('history','实际创作记录')">查看更多 <IconChevronRight :size="13"/></button></header><div class="im-recent"><button v-for="i in (referenceMode?4:Math.min(4,studio.designs.length))" @click="show('history','实际创作记录')"><Art v-if="referenceMode" :name="'recent-'+(i-1)" alt="作品缩略示例"/><img v-else-if="seals.find(s=>s.id===studio.designs[i-1]?.seal_id)?.original_url" :src="seals.find(s=>s.id===studio.designs[i-1]?.seal_id)?.original_url" alt="实际作品缩略图"/><IconCube v-else :size="30"/><span>{{referenceMode?names[i-1]:studio.designs[i-1]?.title}}<small>{{referenceMode?['汉印 · 阳刻','宋式 · 阴刻','明清 · 混合','唐印 · 阴刻'][i-1]:studio.designs[i-1]?.source_kind==="native_typeset"?'规范字排版':'参数草案'}}</small></span><time>{{referenceMode?['2小时前','1天前','3天前','5天前'][i-1]:studio.designs[i-1]?.created_at.slice(0,10)}}</time><IconDots :size="17"/></button></div></Rect>
<Rect :x="1238" :y="625" :w="416" :h="153" title="发布展示"><header class="im-section-heading"><h2>发布展示</h2><button class="im-subtle" @click="show('account-feature','发布展示')">查看更多 <IconChevronRight :size="13"/></button></header><p v-if="!referenceMode" class="im-empty">未接入公开发布服务。实际作品可导出到本机。</p><div v-else class="im-published"><button v-for="(s,i) in ['东方印象','山河万里','文脉无疆']" @click="show('image',s+' · 视觉示例',{image:'/assets/museum/published-'+i+'.png'})"><Art :name="'published-'+i" :alt="s+'参考画作'"/><span>{{s}}</span><small><IconHeartFilled :size="12"/> {{[256,189,321][i]}}</small></button></div></Rect>
<Rect :x="1238" :y="790" :w="416" :h="135" title="订单管理"><header class="im-section-heading"><h2>订单管理</h2><button class="im-subtle" @click="show('account-feature','订单管理')">查看更多</button></header><p v-if="!referenceMode" class="im-empty">没有真实订单，尚未接入支付与制作服务。</p><div v-else class="im-orders"><button v-for="(s,i) in ['印章定制 · 玄武印','高清导出包','3D模型导出']" @click="i===2?$router.push('/reconstruction'):show('account-feature',s)"><IconShoppingBag :size="16"/><span>{{s}}</span><b>¥ {{[298,39,68][i]}}</b><small>{{i===2?'处理中':'已完成'}}</small><time>2024.12.01</time><IconChevronRight :size="12"/></button></div></Rect>
</template>
